// I100 Format C - Structured records
class Cat253I100FormatC {
public:
    const uint8& record_type() const { return record_type_; }
    uint8& mutable_record_type() { return record_type_; }
    void set_record_type(const uint8& v) { record_type_ = v; }

    const uint8& record_count() const { return record_count_; }
    uint8& mutable_record_count() { return record_count_; }
    void set_record_count(const uint8& v) { record_count_ = v; }

    const std::vector<recordsElement>& records() const { return records_; }
    std::vector<recordsElement>& mutable_records() { return records_; }
    void set_records(const std::vector<recordsElement>& v) { records_ = v; }

    bool operator==(const Cat253I100FormatC&) const = default;

    conduit::VoidResult encode(conduit::io::BitWriter& w) const {
        w.write_u8(static_cast<uint8_t>(record_type_));
        w.write_u8(static_cast<uint8_t>(record_count_));
        for (const auto& elem : records_) {
            CONDUIT_TRY(elem.encode(w));
        }
        if (w.has_error()) return std::unexpected(w.error());
        return {};
    }

    static conduit::Result<Cat253I100FormatC> decode(conduit::io::BitReader& r) {
        Cat253I100FormatC result;
        {
            auto val = r.read_u8();
            if (!val) return std::unexpected(val.error().with_context("field 'record-type'"));
            result.record_type_ = static_cast<uint8>(*val);
        }
        {
            auto val = r.read_u8();
            if (!val) return std::unexpected(val.error().with_context("field 'record-count'"));
            result.record_count_ = static_cast<uint8>(*val);
        }
        {
            auto count = static_cast<size_t>(result.record_count_);
            if (count > static_cast<size_t>(INT32_MAX)) return std::unexpected(conduit::Error(conduit::ErrorCode::InvalidArgument, "invalid array count").with_context("array 'records'"));
            result.records_.reserve(count);
            for (size_t i = 0; i < count; i++) {
                auto elem = recordsElement::decode(r);
                if (!elem) return std::unexpected(elem.error().with_context("array 'records'"));
                result.records_.push_back(std::move(*elem));
            }
        }
        return result;
    }

    std::string to_string() const {
        std::ostringstream oss;
        oss << "Cat253I100FormatC{"
            << "record-type=" << +(record_type_)
            << ", record-count=" << +(record_count_)
            << ", records=["
            ;
            for (size_t i = 0; i < records_.size(); ++i) {
                if (i > 0) oss << ", ";
                oss << records_[i].to_string();
            }
            oss << "]"
            << "}";
        return oss.str();
    }

private:
    uint8 record_type_{};
    uint8 record_count_{};
    std::vector<recordsElement> records_{};
};

// I100 Format D - Geographic position data
class Cat253I100FormatD {
public:
    const wgs84_fine& latitude() const { return latitude_; }
    wgs84_fine& mutable_latitude() { return latitude_; }
    void set_latitude(const wgs84_fine& v) { latitude_ = v; }

    const wgs84_fine& longitude() const { return longitude_; }
    wgs84_fine& mutable_longitude() { return longitude_; }
    void set_longitude(const wgs84_fine& v) { longitude_ = v; }

    const double& altitude() const { return altitude_; }
    double& mutable_altitude() { return altitude_; }
    void set_altitude(const double& v) { altitude_ = v; }

    const double& ground_speed() const { return ground_speed_; }
    double& mutable_ground_speed() { return ground_speed_; }
    void set_ground_speed(const double& v) { ground_speed_ = v; }

    const double& heading() const { return heading_; }
    double& mutable_heading() { return heading_; }
    void set_heading(const double& v) { heading_ = v; }

    static constexpr size_t WIRE_SIZE = 16;

    bool operator==(const Cat253I100FormatD&) const = default;

    conduit::VoidResult encode(conduit::io::BitWriter& w) const {
        CONDUIT_TRY(latitude_.encode(w));
        CONDUIT_TRY(longitude_.encode(w));
        w.write_signed_bits(static_cast<int32_t>(altitude_ / 0.25), 32);
        w.write_u16(static_cast<uint16_t>(static_cast<uint16_t>(ground_speed_ / 0.1)), conduit::io::Endian::Big);
        w.write_u16(static_cast<uint16_t>(static_cast<uint16_t>(heading_ / 0.0054931640625)), conduit::io::Endian::Big);
        if (w.has_error()) return std::unexpected(w.error());
        return {};
    }

    static conduit::Result<Cat253I100FormatD> decode(conduit::io::BitReader& r) {
        Cat253I100FormatD result;
        {
            auto val = wgs84_fine::decode(r);
            if (!val) return std::unexpected(val.error().with_context("field 'latitude'"));
            result.latitude_ = std::move(*val);
        }
        {
            auto val = wgs84_fine::decode(r);
            if (!val) return std::unexpected(val.error().with_context("field 'longitude'"));
            result.longitude_ = std::move(*val);
        }
        {
            auto val = ([&]() -> conduit::Result<int32_t> { auto v = r.read_u32(conduit::io::Endian::Big); if (!v) return std::unexpected(v.error()); return static_cast<int32_t>(*v); })();
            if (!val) return std::unexpected(val.error().with_context("field 'altitude'"));
            result.altitude_ = static_cast<double>(*val) * 0.25 + 0;
        }
        {
            auto val = r.read_u16(conduit::io::Endian::Big);
            if (!val) return std::unexpected(val.error().with_context("field 'ground-speed'"));
            result.ground_speed_ = static_cast<double>(*val) * 0.1 + 0;
        }
        {
            auto val = r.read_u16(conduit::io::Endian::Big);
            if (!val) return std::unexpected(val.error().with_context("field 'heading'"));
            result.heading_ = static_cast<double>(*val) * 0.0054931640625 + 0;
        }
        return result;
    }

    std::string to_string() const {
        std::ostringstream oss;
        oss << "Cat253I100FormatD{"
            << "latitude=" << latitude_.value()
            << ", longitude=" << longitude_.value()
            << ", altitude=" << +(altitude_)
            << ", ground-speed=" << +(ground_speed_)
            << ", heading=" << +(heading_)
            << "}";
        return oss.str();
    }

private:
    wgs84_fine latitude_{};
    wgs84_fine longitude_{};
    double altitude_{};
    double ground_speed_{};
    double heading_{};
};

