class sub_items {
public:
    bool has_source_id() const { return source_id_.has_value(); }
    const DataSourceId& source_id() const { return source_id_.value(); }
    DataSourceId& mutable_source_id() { if (!source_id_) source_id_.emplace(); return *source_id_; }
    void set_source_id(const DataSourceId& v) { source_id_ = v; }
    void clear_source_id() { source_id_.reset(); }

    bool has_callsign() const { return callsign_.has_value(); }
    const ::asterix::callsign& callsign() const { return callsign_.value(); }
    ::asterix::callsign& mutable_callsign() { if (!callsign_) callsign_.emplace(); return *callsign_; }
    void set_callsign(const ::asterix::callsign& v) { callsign_ = v; }
    void clear_callsign() { callsign_.reset(); }

    bool has_aircraft_addr() const { return aircraft_addr_.has_value(); }
    const aircraft_address& aircraft_addr() const { return aircraft_addr_.value(); }
    aircraft_address& mutable_aircraft_addr() { if (!aircraft_addr_) aircraft_addr_.emplace(); return *aircraft_addr_; }
    void set_aircraft_addr(const aircraft_address& v) { aircraft_addr_ = v; }
    void clear_aircraft_addr() { aircraft_addr_.reset(); }

    bool has_position() const { return position_.has_value(); }
    const ::asterix::position& position() const { return position_.value(); }
    ::asterix::position& mutable_position() { if (!position_) position_.emplace(); return *position_; }
    void set_position(const ::asterix::position& v) { position_ = v; }
    void clear_position() { position_.reset(); }

    bool has_flight_level() const { return flight_level_.has_value(); }
    const ::asterix::flight_level& flight_level() const { return flight_level_.value(); }
    ::asterix::flight_level& mutable_flight_level() { if (!flight_level_) flight_level_.emplace(); return *flight_level_; }
    void set_flight_level(const ::asterix::flight_level& v) { flight_level_ = v; }
    void clear_flight_level() { flight_level_.reset(); }

    bool has_track_number() const { return track_number_.has_value(); }
    const ::asterix::track_number& track_number() const { return track_number_.value(); }
    ::asterix::track_number& mutable_track_number() { if (!track_number_) track_number_.emplace(); return *track_number_; }
    void set_track_number(const ::asterix::track_number& v) { track_number_ = v; }
    void clear_track_number() { track_number_.reset(); }

    bool has_velocity() const { return velocity_.has_value(); }
    const ::asterix::velocity& velocity() const { return velocity_.value(); }
    ::asterix::velocity& mutable_velocity() { if (!velocity_) velocity_.emplace(); return *velocity_; }
    void set_velocity(const ::asterix::velocity& v) { velocity_ = v; }
    void clear_velocity() { velocity_.reset(); }

    bool operator==(const sub_items&) const = default;

    conduit::VoidResult encode(conduit::io::BitWriter& w) const {
        std::array<uint8_t, 1> fspec{};
        if (source_id_.has_value()) fspec[0] |= (1 << 7);
        if (callsign_.has_value()) fspec[0] |= (1 << 6);
        if (aircraft_addr_.has_value()) fspec[0] |= (1 << 5);
        if (position_.has_value()) fspec[0] |= (1 << 4);
        if (flight_level_.has_value()) fspec[0] |= (1 << 3);
        if (track_number_.has_value()) fspec[0] |= (1 << 2);
        if (velocity_.has_value()) fspec[0] |= (1 << 1);
        w.write_bytes(std::span<const uint8_t>(fspec.data(), 1));
        if (source_id_.has_value()) {
            CONDUIT_TRY(source_id_->encode(w));
        }
        if (callsign_.has_value()) {
            CONDUIT_TRY(callsign_->encode(w));
        }
        if (aircraft_addr_.has_value()) {
            w.write_bits(*aircraft_addr_, 24);
        }
        if (position_.has_value()) {
            CONDUIT_TRY(position_->encode(w));
        }
        if (flight_level_.has_value()) {
            CONDUIT_TRY(flight_level_->encode(w));
        }
        if (track_number_.has_value()) {
            w.write_bits(*track_number_, 16);
        }
        if (velocity_.has_value()) {
            CONDUIT_TRY(velocity_->encode(w));
        }
        if (w.has_error()) return std::unexpected(w.error());
        return {};
    }

    static conduit::Result<sub_items> decode(conduit::io::BitReader& r) {
        sub_items result;

        // Read FSPEC bitmap
        std::array<uint8_t, 1> fspec{};
        size_t fspec_len = 0;
        for (size_t i = 0; i < 1; i++) {
            auto byte = r.read_u8();
            if (!byte) return std::unexpected(byte.error());
            fspec[i] = *byte;
        }
        fspec_len = 1;

        if (fspec_len > 0 && (fspec[0] & (1 << 7))) {
            auto val = DataSourceId::decode(r);
            if (!val) return std::unexpected(val.error());
            result.source_id_ = std::move(*val);
        }
        if (fspec_len > 0 && (fspec[0] & (1 << 6))) {
            auto val = ::asterix::callsign::decode(r);
            if (!val) return std::unexpected(val.error());
            result.callsign_ = std::move(*val);
        }
        if (fspec_len > 0 && (fspec[0] & (1 << 5))) {
            auto val = r.read_bits(24);
            if (!val) return std::unexpected(val.error());
            result.aircraft_addr_ = static_cast<aircraft_address>(*val);
        }
        if (fspec_len > 0 && (fspec[0] & (1 << 4))) {
            auto val = ::asterix::position::decode(r);
            if (!val) return std::unexpected(val.error());
            result.position_ = std::move(*val);
        }
        if (fspec_len > 0 && (fspec[0] & (1 << 3))) {
            auto val = ::asterix::flight_level::decode(r);
            if (!val) return std::unexpected(val.error());
            result.flight_level_ = std::move(*val);
        }
        if (fspec_len > 0 && (fspec[0] & (1 << 2))) {
            auto val = r.read_bits(16);
            if (!val) return std::unexpected(val.error());
            result.track_number_ = static_cast<::asterix::track_number>(*val);
        }
        if (fspec_len > 0 && (fspec[0] & (1 << 1))) {
            auto val = ::asterix::velocity::decode(r);
            if (!val) return std::unexpected(val.error());
            result.velocity_ = std::move(*val);
        }

        return result;
    }

    std::string to_string() const {
        std::ostringstream oss;
        oss << "sub_items{";
        bool first = true;
        if (source_id_.has_value()) {
            if (!first) oss << ", ";
            first = false;
            oss << "source-id=" << (*source_id_).to_string();
        }
        if (callsign_.has_value()) {
            if (!first) oss << ", ";
            first = false;
            oss << "callsign=" << (*callsign_).value();
        }
        if (aircraft_addr_.has_value()) {
            if (!first) oss << ", ";
            first = false;
            oss << "aircraft-addr=0x" << std::hex << static_cast<uint64_t>(*aircraft_addr_) << std::dec;
        }
        if (position_.has_value()) {
            if (!first) oss << ", ";
            first = false;
            oss << "position=" << (*position_).to_string();
        }
        if (flight_level_.has_value()) {
            if (!first) oss << ", ";
            first = false;
            oss << "flight-level=" << (*flight_level_).value();
        }
        if (track_number_.has_value()) {
            if (!first) oss << ", ";
            first = false;
            oss << "track-number=" << static_cast<uint64_t>(*track_number_);
        }
        if (velocity_.has_value()) {
            if (!first) oss << ", ";
            first = false;
            oss << "velocity=" << (*velocity_).to_string();
        }
        oss << "}";
        return oss.str();
    }

private:
    std::optional<DataSourceId> source_id_;
    std::optional<::asterix::callsign> callsign_;
    std::optional<aircraft_address> aircraft_addr_;
    std::optional<::asterix::position> position_;
    std::optional<::asterix::flight_level> flight_level_;
    std::optional<::asterix::track_number> track_number_;
    std::optional<::asterix::velocity> velocity_;
};

